/* CineMatch — front-end
 * Data comes from data/movies.js (generated by ml/build_model.py):
 *   MOVIE_DATA.movies  -> list of movies
 *   MOVIE_DATA.recs    -> { movieId: [[recId, similarity, [reasons]], ...] }
 *   MOVIE_DATA.stats   -> dataset insights
 *   MOVIE_DATA.metrics -> model evaluation
 * Posters are fetched from Wikipedia at runtime and cached in localStorage.
 */
(function () {
  "use strict";

  const DATA = window.MOVIE_DATA;
  if (!DATA) {
    document.body.innerHTML = "<p style='padding:40px'>data/movies.js not found. Run <code>python ml/build_model.py</code>.</p>";
    return;
  }

  const movies = DATA.movies;
  const byId = new Map(movies.map((m) => [m.id, m]));
  const $ = (sel) => document.querySelector(sel);
  const esc = (s) =>
    String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

  /* ------------------------------------------------------------ POSTERS */
  const CACHE_KEY = "cinematch-posters-v1";
  let posterCache = {};
  try { posterCache = JSON.parse(localStorage.getItem(CACHE_KEY) || "{}"); } catch (e) { posterCache = {}; }
  const inflight = new Map();

  function saveCache() {
    try { localStorage.setItem(CACHE_KEY, JSON.stringify(posterCache)); } catch (e) { /* storage unavailable */ }
  }

  async function fromSummary(wiki) {
    const url = "https://en.wikipedia.org/api/rest_v1/page/summary/" + encodeURIComponent(wiki);
    const res = await fetch(url, { headers: { Accept: "application/json" } });
    if (!res.ok) return null;
    const j = await res.json();
    return (j.originalimage && j.originalimage.source) || (j.thumbnail && j.thumbnail.source) || null;
  }

  async function fromSearch(movie) {
    const q = `${movie.title} ${movie.year} film`;
    const url =
      "https://en.wikipedia.org/w/api.php?action=query&format=json&origin=*&generator=search&gsrlimit=1" +
      "&prop=pageimages&piprop=thumbnail&pithumbsize=500&gsrsearch=" + encodeURIComponent(q);
    const res = await fetch(url);
    if (!res.ok) return null;
    const j = await res.json();
    const pages = j.query && j.query.pages ? Object.values(j.query.pages) : [];
    return pages[0] && pages[0].thumbnail ? pages[0].thumbnail.source : null;
  }

  function getPoster(movie) {
    if (movie.wiki in posterCache) return Promise.resolve(posterCache[movie.wiki]);
    if (inflight.has(movie.wiki)) return inflight.get(movie.wiki);
    const p = (async () => {
      let src = null;
      let networkError = false;
      try { src = await fromSummary(movie.wiki); } catch (e) { networkError = true; }
      if (!src) { try { src = await fromSearch(movie); } catch (e) { networkError = true; } }
      if (src || !networkError) { posterCache[movie.wiki] = src; saveCache(); } // don't cache offline failures
      inflight.delete(movie.wiki);
      return src;
    })();
    inflight.set(movie.wiki, p);
    return p;
  }

  // deterministic colour pair for the fallback poster
  function hues(title) {
    let h = 0;
    for (const ch of title) h = (h * 31 + ch.charCodeAt(0)) % 360;
    return [`hsl(${h} 45% 30%)`, `hsl(${(h + 60) % 360} 40% 12%)`];
  }

  function posterHTML(m) {
    const [a, b] = hues(m.title);
    return `<div class="poster loading" data-wiki="${esc(m.wiki)}" data-id="${m.id}" style="--h1:${a};--h2:${b}">
        <div class="fallback">${esc(m.title)}<small>${m.year}</small></div>
      </div>`;
  }

  function loadPoster(el) {
    const m = byId.get(Number(el.dataset.id));
    if (!m || el.dataset.done) return;
    el.dataset.done = "1";
    getPoster(m).then((src) => {
      el.classList.remove("loading");
      if (!src) return;
      const img = new Image();
      img.alt = m.title + " poster";
      img.decoding = "async";
      img.referrerPolicy = "no-referrer";
      img.onload = () => { img.classList.add("loaded"); el.classList.add("has-img"); };
      img.onerror = () => img.remove();
      img.src = src;
      el.prepend(img);
    });
  }

  const io = "IntersectionObserver" in window
    ? new IntersectionObserver((entries) => {
        entries.forEach((e) => { if (e.isIntersecting) { loadPoster(e.target); io.unobserve(e.target); } });
      }, { rootMargin: "300px" })
    : null;

  function hydratePosters(root) {
    root.querySelectorAll(".poster[data-id]").forEach((el) => (io ? io.observe(el) : loadPoster(el)));
  }

  /* ------------------------------------------------------------ SEARCH */
  const input = $("#searchInput");
  const list = $("#suggestions");
  let active = -1;
  let matches = [];

  const norm = (s) => s.toLowerCase().normalize("NFD").replace(/[̀-ͯ]/g, "").replace(/[^a-z0-9 ]/g, "");

  function renderSuggestions() {
    const q = norm(input.value.trim());
    if (!q) { list.innerHTML = ""; matches = []; return; }
    matches = movies
      .map((m) => {
        const t = norm(m.title);
        const score = t.startsWith(q) ? 0 : t.includes(q) ? 1 : m.cast.some((c) => norm(c).includes(q)) ? 2 : -1;
        return { m, score };
      })
      .filter((x) => x.score >= 0)
      .sort((a, b) => a.score - b.score || b.m.rating - a.m.rating)
      .slice(0, 8)
      .map((x) => x.m);
    active = matches.length ? 0 : -1;
    list.innerHTML = matches.length
      ? matches.map((m, i) =>
          `<li role="option" data-id="${m.id}" class="${i === active ? "active" : ""}">
             <span>${esc(m.title)}</span><small>${m.year} · ${esc(m.language)}</small>
           </li>`).join("")
      : `<li style="cursor:default"><span class="muted">No match in the catalogue</span></li>`;
  }

  input.addEventListener("input", renderSuggestions);
  input.addEventListener("keydown", (e) => {
    if (!matches.length) return;
    if (e.key === "ArrowDown" || e.key === "ArrowUp") {
      e.preventDefault();
      active = (active + (e.key === "ArrowDown" ? 1 : -1) + matches.length) % matches.length;
      [...list.children].forEach((li, i) => li.classList.toggle("active", i === active));
    } else if (e.key === "Enter" && active >= 0) {
      select(matches[active].id);
    } else if (e.key === "Escape") {
      list.innerHTML = "";
    }
  });
  list.addEventListener("mousedown", (e) => {
    const li = e.target.closest("li[data-id]");
    if (li) select(Number(li.dataset.id));
  });
  input.addEventListener("blur", () => setTimeout(() => (list.innerHTML = ""), 120));

  $("#surpriseBtn").addEventListener("click", () => select(movies[Math.floor(Math.random() * movies.length)].id));
  $("#homeLink").addEventListener("click", (e) => {
    e.preventDefault();
    history.replaceState(null, "", location.pathname);
    $("#result").classList.add("hidden");
    window.scrollTo({ top: 0, behavior: "smooth" });
  });

  // quick picks
  const QUICK = ["3 Idiots", "Inception", "Dangal", "The Dark Knight", "Drishyam", "Toy Story", "The Godfather"];
  $("#quickPicks").innerHTML = QUICK
    .map((t) => movies.find((m) => m.title === t))
    .filter(Boolean)
    .map((m) => `<button class="chip" data-id="${m.id}">${esc(m.title)}</button>`)
    .join("");
  $("#quickPicks").addEventListener("click", (e) => {
    const b = e.target.closest("[data-id]");
    if (b) select(Number(b.dataset.id));
  });

  /* ------------------------------------------------------------ RECOMMEND */
  function select(id, opts = {}) {
    const m = byId.get(id);
    if (!m) return;
    input.value = "";
    list.innerHTML = "";
    matches = [];

    const wikiUrl = "https://en.wikipedia.org/wiki/" + encodeURIComponent(m.wiki);
    $("#selected").innerHTML = `
      <div class="backdrop"></div>
      ${posterHTML(m)}
      <div>
        <p class="eyebrow" style="margin-bottom:6px">Selected movie</p>
        <h2>${esc(m.title)}</h2>
        <div class="meta">
          <span>${m.year}</span><span>${esc(m.language)}</span>
          <span class="star">★ ${m.rating.toFixed(1)}</span>
        </div>
        <div class="pills">${m.genres.map((g) => `<span class="pill">${esc(g)}</span>`).join("")}</div>
        <p class="overview">${esc(m.overview)}</p>
        <div class="credits">
          ${m.director.length ? `<div>Director: <b>${esc(m.director.join(", "))}</b></div>` : ""}
          <div>Cast: <b>${esc(m.cast.join(", "))}</b></div>
        </div>
        <a class="wiki-link" href="${wikiUrl}" target="_blank" rel="noopener">Read on Wikipedia ↗</a>
      </div>`;
    const sel = $("#selected .poster");
    loadPoster(sel);
    getPoster(m).then((src) => {
      if (src) $("#selected .backdrop").style.backgroundImage = `url("${src}")`;
    });

    $("#selTitle").textContent = m.title;
    const recs = DATA.recs[m.id] || [];
    const top = recs.length ? recs[0][1] : 1;
    $("#recGrid").innerHTML = recs
      .map(([rid, score, why], i) => {
        const r = byId.get(rid);
        const pct = Math.round(score * 100);
        const width = Math.max(6, Math.round((score / top) * 100));
        return `
          <button class="card" data-id="${r.id}" style="animation-delay:${i * 40}ms">
            <div class="poster-wrap"><span class="rank">#${i + 1}</span>${posterHTML(r)}</div>
            <div>
              <div class="title">${esc(r.title)}</div>
              <div class="sub">${r.year} · ${esc(r.genres.slice(0, 2).join(", "))} · ★ ${r.rating.toFixed(1)}</div>
            </div>
            <div class="score"><span>${pct}% match</span><span class="bar"><i style="width:${width}%"></i></span></div>
            <div class="why">${why.slice(0, 3).map((w) => `<span>${esc(w)}</span>`).join("")}</div>
          </button>`;
      })
      .join("");
    hydratePosters($("#recGrid"));

    $("#result").classList.remove("hidden");
    if (!opts.silent) {
      history.replaceState(null, "", "#movie=" + m.id);
      $("#result").scrollIntoView({ behavior: "smooth", block: "start" });
    }
  }

  $("#recGrid").addEventListener("click", (e) => {
    const c = e.target.closest(".card");
    if (c) select(Number(c.dataset.id));
  });

  /* ------------------------------------------------------------ BROWSE */
  const state = { genre: "All", lang: "All", sort: "rating" };
  const genres = ["All", ...Object.keys(DATA.stats.genres)];
  const langs = ["All", ...Object.keys(DATA.stats.languages)];

  $("#genreChips").innerHTML = genres
    .map((g) => `<button class="chip ${g === "All" ? "on" : ""}" data-g="${esc(g)}">${esc(g)}</button>`)
    .join("");
  $("#langFilter").innerHTML = langs
    .map((l) => `<option value="${esc(l)}">${l === "All" ? "All languages" : esc(l)}</option>`)
    .join("");

  function renderBrowse() {
    let rows = movies.filter(
      (m) => (state.genre === "All" || m.genres.includes(state.genre)) && (state.lang === "All" || m.language === state.lang)
    );
    const sorters = {
      rating: (a, b) => b.rating - a.rating,
      new: (a, b) => b.year - a.year,
      az: (a, b) => a.title.localeCompare(b.title),
    };
    rows = rows.sort(sorters[state.sort]);
    $("#browseCount").textContent = `${rows.length} movie${rows.length === 1 ? "" : "s"} · click any to get recommendations`;
    $("#browseGrid").innerHTML = rows
      .map((m) => `
        <button class="card" data-id="${m.id}">
          ${posterHTML(m)}
          <div><div class="title">${esc(m.title)}</div><div class="sub">${m.year} · ★ ${m.rating.toFixed(1)}</div></div>
        </button>`)
      .join("");
    hydratePosters($("#browseGrid"));
  }

  $("#genreChips").addEventListener("click", (e) => {
    const b = e.target.closest("[data-g]");
    if (!b) return;
    state.genre = b.dataset.g;
    [...$("#genreChips").children].forEach((c) => c.classList.toggle("on", c === b));
    renderBrowse();
  });
  $("#langFilter").addEventListener("change", (e) => { state.lang = e.target.value; renderBrowse(); });
  $("#sortBy").addEventListener("change", (e) => { state.sort = e.target.value; renderBrowse(); });
  $("#browseGrid").addEventListener("click", (e) => {
    const c = e.target.closest(".card");
    if (c) select(Number(c.dataset.id));
  });

  /* ------------------------------------------------------------ INSIGHTS */
  function bars(el, obj) {
    const max = Math.max(...Object.values(obj));
    el.innerHTML = Object.entries(obj)
      .map(([k, v]) => `
        <div class="hbar"><span class="lbl" title="${esc(k)}">${esc(k)}</span>
          <span class="trk"><i style="width:${(v / max) * 100}%"></i></span><span class="val">${v}</span></div>`)
      .join("");
  }

  const s = DATA.stats, mt = DATA.metrics;
  $("#tiles").innerHTML = [
    [mt.movies, "movies after cleaning"],
    [Object.keys(s.languages).length, "languages"],
    [s.avg_rating.toFixed(2), "average rating"],
    [mt.tfidf_precision + "%", `of top-${mt.top_n} picks share a genre`],
  ].map(([v, l]) => `<div class="tile"><b>${v}</b><span>${l}</span></div>`).join("");
  bars($("#chartGenres"), s.genres);
  bars($("#chartLang"), s.languages);
  bars($("#chartDecade"), s.decades);

  /* ------------------------------------------------------------ INIT */
  renderBrowse();
  const fromHash = location.hash.match(/movie=(\d+)/);
  if (fromHash) select(Number(fromHash[1]), { silent: true });
})();
